// Lossless RGBA compression, independently bounded before allocation/decompression.
const cache=new WeakMap(),MAX_BYTES=160*1024*1024;
const base64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(s);};
async function stream(bytes,compress,limit){const reader=new Blob([bytes]).stream().pipeThrough(compress?new CompressionStream('gzip'):new DecompressionStream('gzip')).getReader(),chunks=[];let length=0;try{while(true){const r=await reader.read();if(r.done)break;length+=r.value.length;if(length>limit)throw Error('壓縮資料超過宣告大小');chunks.push(r.value);}}finally{await reader.cancel().catch(()=>{});}const out=new Uint8Array(length);let at=0;for(const c of chunks){out.set(c,at);at+=c.length;}return out;}
const hash=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');
async function encode(pixels){const bytes=Uint8Array.from(pixels),packed=await stream(bytes,true,MAX_BYTES);return {encoding:'rgba8-gzip-base64',length:bytes.length,sha256:await hash(bytes),data:base64(packed)};}
async function decode(block,expected){if(!block||block.encoding!=='rgba8-gzip-base64'||block.length!==expected||typeof block.data!=='string'||block.data.length>MAX_BYTES*1.4||!/^[a-f0-9]{64}$/.test(block.sha256))throw Error('壓縮像素欄位無效');let bytes;try{bytes=Uint8Array.from(atob(block.data),c=>c.charCodeAt(0));}catch{throw Error('壓縮像素編碼無效');}const out=await stream(bytes,false,expected);if(out.length!==expected||await hash(out)!==block.sha256)throw Error('專案像素校驗失敗');return out;}
export async function packProject(p){const {source,...rest}=p,project=structuredClone(rest);let encoded=cache.get(source);if(!encoded){encoded=encode(source.pixels);cache.set(source,encoded);encoded.catch(()=>cache.delete(source));}project.source={width:source.width,height:source.height,rgba:await encoded};for(const f of project.frames)for(const id of Object.keys(f.cels))f.cels[id]=await encode(f.cels[id]);return {format:'bitdraw-packed',version:1,project};}
export async function unpackProject(input){if(input?.format!=='bitdraw-packed')return input;if(input.version!==1||!input.project)throw Error('不支援的壓縮專案版本');const p=structuredClone(input.project),s=p.source,valid=(v,max)=>Number.isInteger(v)&&v>=1&&v<=max;if(!s||!valid(s.width,8192)||!valid(s.height,8192)||s.width*s.height>8_388_608||!valid(p.width,1024)||!valid(p.height,1024)||!Array.isArray(p.frames)||p.frames.length!==1||!p.frames[0].cels||Object.keys(p.frames[0].cels).length>16)throw Error('壓縮專案尺寸無效');p.source={width:s.width,height:s.height,pixels:await decode(s.rgba,s.width*s.height*4)};for(const f of p.frames)for(const id of Object.keys(f.cels))f.cels[id]=Array.from(await decode(f.cels[id],p.width*p.height*4));return p;}
export function legacyProject(p){return {...p,source:{...p.source,pixels:Array.from(p.source.pixels)}};}
